const item = $input.first();
const binaries = item.binary || {};
const body = item.json.body || {};

const keys = Object.keys(binaries)
  .filter((k) => /^cvs\d*$/i.test(k) || k === 'cvs')
  .sort((a, b) => {
    const na = parseInt(a.replace(/\D/g, ''), 10);
    const nb = parseInt(b.replace(/\D/g, ''), 10);
    if (Number.isFinite(na) && Number.isFinite(nb)) return na - nb;
    return a.localeCompare(b);
  });

if (!keys.length) {
  throw new Error('No CV PDF binaries found (expected cvs0, cvs1, …)');
}

return keys.map((key) => ({
  json: {
    fileName: binaries[key].fileName || key,
    comparisonId: body.comparisonId,
    position: body.position,
    location: body.location,
    criteria: body.criteria,
    callbackUrl: body.callbackUrl,
  },
  binary: {
    data: binaries[key],
  },
}));

const agentOut = $input.first().json;
let raw = agentOut.output ?? agentOut.text ?? agentOut.response ?? agentOut;
let parsed = {};

if (typeof raw === 'string') {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start >= 0 && end > start) {
    try { parsed = JSON.parse(raw.slice(start, end + 1)); } catch (e) { parsed = {}; }
  }
} else if (raw && typeof raw === 'object') {
  if (raw.candidates) parsed = raw;
  else if (raw.parsed && typeof raw.parsed === 'object') parsed = raw.parsed;
  else if (typeof raw.output === 'string') {
    const start = raw.output.indexOf('{');
    const end = raw.output.lastIndexOf('}');
    if (start >= 0 && end > start) {
      try { parsed = JSON.parse(raw.output.slice(start, end + 1)); } catch (e) { parsed = {}; }
    }
  }
}

const webhook = $('Webhook').first().json.body || {};
const filterItems = $('Filter CV Documents').all();
const skippedFromFilter = filterItems.find((i) => Array.isArray(i.json.skippedFiles))?.json.skippedFiles || [];
const validCvFiles = filterItems.filter((i) => i.json.isCv).map((i) => i.json.fileName);

const candidates = Array.isArray(parsed.candidates) ? parsed.candidates : [];

function looksLikeNonCvCandidate(c) {
  const name = String(c?.name || '').toLowerCase();
  const summary = String(c?.summary || '').toLowerCase();
  if (name.includes('no text') || name.includes('(no text)')) return true;
  if (summary.includes('no extractable text') || summary.includes('not a cv') || summary.includes('not a resume')) return true;
  if (summary.includes('little or no') && summary.includes('text')) return true;
  return false;
}

const filteredCandidates = candidates.filter((c) => !looksLikeNonCvCandidate(c));

const comparisons = filteredCandidates.map((c, idx) => ({
  fileName: c.name || validCvFiles[idx] || `CV ${idx + 1}`,
  name: c.name || validCvFiles[idx] || `CV ${idx + 1}`,
  rank: idx + 1,
  score: c.overallScore ?? c.score ?? null,
  matchScore: c.overallScore ?? c.score ?? null,
  summary: c.summary || '',
  finalHrReport:
    c.finalHrReport ||
    c.finalHrEvaluation ||
    c.final_hr_report ||
    c.hrReport ||
    '',
  skills: Array.isArray(c.skills) ? c.skills : [],
  experienceYears: c.experienceYears ?? null,
  education: c.education || '',
  strengths: Array.isArray(c.strengths) ? c.strengths : [],
  weaknesses: Array.isArray(c.weaknesses) ? c.weaknesses : [],
  isCv: true,
}));

return [{
  json: {
    comparisonId: webhook.comparisonId,
    callbackUrl: webhook.callbackUrl,
    comparisons,
    candidates: filteredCandidates,
    ranking: (parsed.ranking || []).filter((name) =>
      comparisons.some((c) => c.name === name || c.fileName === name)
    ),
    recommendation: parsed.recommendation || '',
    comparisonSummary: parsed.comparisonSummary || '',
    skippedFiles: skippedFromFilter,
  },
}];

const item = $input.first();
const body = item.json.body ?? {};

const reject = (reason) => [{
  json: { passed: false, rejectReason: reason, body },
  binary: item.binary,
}];

if (!String(body.comparisonId || '').trim()) {
  return reject('Missing comparisonId');
}
if (!String(body.callbackUrl || '').trim()) {
  return reject('Missing callbackUrl');
}
if (!String(body.position || '').trim()) {
  return reject('Missing position');
}
if (!String(body.location || '').trim()) {
  return reject('Missing location');
}
if (!String(body.inboundSecret || '').trim()) {
  return reject('Missing inboundSecret');
}

return [{
  json: { passed: true, rejectReason: '', body },
  binary: item.binary,
}];

const item = $input.first();
const prev = item.json;
if (!prev.passed) {
  return [{ json: prev, binary: item.binary }];
}

const body = prev.body || {};
const urlStr = String(body.callbackUrl || '').trim();

const reject = (reason) => [{
  json: { passed: false, rejectReason: reason, body },
  binary: item.binary,
}];

if (!urlStr) {
  return reject('Missing callbackUrl');
}

if (urlStr.includes('@') || /\/redirect\//i.test(urlStr)) {
  return reject('Redirect or credential URLs are not allowed');
}

const m = urlStr.match(/^(https?):\/\/([^\/?#:]+)(?::(\d+))?(\/[^?#]*)?(?:\?([^#]*))?/i);
if (!m) {
  return reject('Invalid callbackUrl');
}

const scheme = String(m[1] || '').toLowerCase();
const host = String(m[2] || '');
let port = m[3] ? String(m[3]) : '';
const pathname = m[4] || '/';
const query = m[5] || '';

if (host.includes('*')) {
  return reject('Wildcard hostnames are not allowed');
}

if (!port) {
  port = scheme === 'https' ? '443' : '80';
}

let origin;
if (scheme === 'https' && port === '443') {
  origin = 'https://' + host;
} else if (scheme === 'http' && port === '80') {
  origin = 'http://' + host;
} else {
  origin = scheme + '://' + host + ':' + port;
}

const allowed = [
  'https://api.evaalo.com',
  'http://100.73.82.78:5000',
];

let ok = false;
for (let i = 0; i < allowed.length; i++) {
  if (allowed[i] === origin) {
    ok = true;
    break;
  }
}

if (!ok) {
  return reject('callbackUrl origin not allowlisted: ' + origin);
}

if (pathname !== '/webhook/n8n/cv-comparison') {
  return reject('callbackUrl path must be /webhook/n8n/cv-comparison');
}

let hasComparisonId = false;
let hasToken = false;
if (query) {
  const parts = query.split('&');
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    const eq = part.indexOf('=');
    const k = eq >= 0 ? decodeURIComponent(part.slice(0, eq)) : part;
    const v = eq >= 0 ? decodeURIComponent(part.slice(eq + 1)) : '';
    if (k === 'comparisonId' && String(v).trim()) hasComparisonId = true;
    if (k === 'token' && String(v).trim()) hasToken = true;
  }
}

if (!hasComparisonId) {
  return reject('callbackUrl must include comparisonId query parameter');
}
if (!hasToken) {
  return reject('callbackUrl must include token query parameter');
}

return [{
  json: { passed: true, rejectReason: '', body },
  binary: item.binary,
}];

const items = $input.all();

function isLikelyCv(text, fileName) {
  const t = String(text || '').replace(/\s+/g, ' ').trim();
  if (t.length < 80) return { ok: false, reason: 'insufficient_text' };

  const lower = t.toLowerCase();
  const cvSignals = [
    'experience', 'education', 'skills', 'employment', 'university', 'bachelor', 'master',
    'resume', 'curriculum vitae', 'objective', 'certification', 'qualified', 'position',
    'career', 'profile', 'languages', 'internship', 'degree',
    'خبرة', 'تعليم', 'مهارات', 'السيرة', 'جامعة', 'مؤهل', 'وظيفة', 'عمل', 'تخصص', 'شهادة'
  ];
  const hits = cvSignals.filter((s) => lower.includes(s)).length;
  const hasEmail = /@[\w.-]+\.\w{2,}/.test(t);
  const hasPhone = /(\+?\d[\d\s\-().]{7,}\d)/.test(t);

  if (hits >= 2) return { ok: true };
  if (hasEmail && (hasPhone || hits >= 1)) return { ok: true };
  if (t.length >= 400 && hits >= 1) return { ok: true };

  const nameHint = String(fileName || '').toLowerCase();
  if (
    (nameHint.includes('cv') || nameHint.includes('resume') || nameHint.includes('سيرة') || nameHint.includes('curriculum')) &&
    t.length >= 120 &&
    hits >= 1
  ) {
    return { ok: true };
  }

  return { ok: false, reason: 'not_cv_like' };
}

const valid = [];
const skipped = [];

for (const item of items) {
  const text = item.json.text ?? item.json.data ?? '';
  const fileName =
    item.json.fileName ||
    item.binary?.data?.fileName ||
    item.binary?.data?.fileName ||
    'unknown.pdf';
  const verdict = isLikelyCv(text, fileName);
  if (verdict.ok) {
    valid.push({
      json: {
        ...item.json,
        fileName,
        text: String(text).trim(),
        isCv: true,
      },
      binary: item.binary,
    });
  } else {
    skipped.push({ fileName, reason: verdict.reason });
  }
}

const webhook = $('Webhook').first().json.body || {};

if (!valid.length) {
  return [{
    json: {
      noValidCvs: true,
      comparisonId: webhook.comparisonId,
      callbackUrl: webhook.callbackUrl,
      skippedFiles: skipped,
      comparisons: [],
      candidates: [],
      ranking: [],
      recommendation: '',
      comparisonSummary:
        skipped.length
          ? 'No valid CV documents were found. Non-CV or unreadable files were ignored.'
          : 'No CV files were provided.',
    },
  }];
}

return valid.map((row, idx) => ({
  json: {
    ...row.json,
    skippedFiles: idx === 0 ? skipped : [],
  },
  binary: row.binary,
}));
